ACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'BRAND\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'L1_CATEGORY\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'L2_CATEGORY\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'L3_CATEGORY\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'PRODUCT_NAME\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'VARIANT\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'ITEM_CODE\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'COMBO_ITEM_CODE\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'COMBO\'), JSON_EXTRACT_PATH_TEXT(JSON_SERIALIZE(_airbyte_data), \'ORDERED_DATE\') ORDER BY DATE_TRUNC(\'second\', _airbyte_emitted_at) DESC ) AS rn FROM public._airbyte_raw_anveshan_swiggy_sales ) SELECT index,brand,ordered_date,city,area_name,store_id,l1_category,l2_category,l3_category, product_name,variant,item_code,combo,combo_item_code,combo_units_sold,base_mrp,units_sold,gmv FROM flattened_ranked WHERE rn = 1; drop table if exists public.anveshan_SWIGGY_SALES_FACT_ITEMS; CREATE TABLE public.anveshan_SWIGGY_SALES_FACT_ITEMS AS SELECT (Store_id || \'-\' || item_code || \'-\' || Area_name || \'-\' || UPPER(coalesce(lm.city,fi.city)) || \'-\' || variant || \'-\' || UNITS_SOLD || \'-\' || GMV || \'-\' || ordered_date)::text AS order_id, CAST(GMV AS NUMERIC) AS selling_price, CASE WHEN TRIM(ordered_date) LIKE \'____-__-__\' THEN CAST(TRIM(ordered_date) AS DATE) WHEN ordered_date::varchar SIMILAR TO \'[0-9]{2}-[0-9]{2}-[0-9]{4}\' THEN TO_DATE(ordered_date::varchar, \'DD-MM-YYYY\') ELSE TO_DATE(TRIM(ordered_date), \'DD/MM/YY\') END AS order_date, ordered_date, UPPER(coalesce(lm.city,fi.city)) AS CITY, lm.state as State, VARIANT, CAST(BASE_MRP AS NUMERIC) AS MRP, STORE_ID, AREA_NAME, ITEM_CODE, CAST(UNITS_SOLD AS NUMERIC) AS quantity, COALESCE(UPPER(p.CATEGORY), UPPER(fi.L2_category)) AS product_category, p.commonsku, p.tax_Rate as pm_tax_rate, p.cogs, UPPER(fi.PRODUCT_NAME) AS PRODUCT_NAME, COALESCE(UPPER(p.Product_name), REPLACE(UPPER(fi.PRODUCT_NAME), \'anveshan \', \'\')) AS product_name_final, cast(gmv as double PRECISION) AS Selling_Price_final FROM public.anveshan_swiggy_instamart_anveshan_s3_instamart fi LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, swiggy_sku as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY swiggy_sku ORDER BY LENGTH(COALESCE(swiggy_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p ON LOWER(REPLACE(REPLACE(fi.item_code::varchar, \' \', \'\'),\'\"\',\'\')) = LOWER(p.marketplace_sku) LEFT JOIN (select * FROM ( select upper(city::varchar) as City, upper(trim(state::varchar)) as State, upper(trim(\"quick commerce city\"::varchar)) as qc_city_name, row_number() over (partition by upper(trim(\"quick commerce city\"::varchar)) order by 1) as rw FROM public.anveshan_qc_location_mapping ) where rw = 1 ) lm ON lower(lm.qc_city_name) = lower(cast(fi.city as varchar)) where (CASE WHEN TRIM(ordered_date) LIKE \'____-__-__\' THEN CAST(TRIM(ordered_date) AS DATE) WHEN ordered_date::varchar SIMILAR TO \'[0-9]{2}-[0-9]{2}-[0-9]{4}\' THEN TO_DATE(ordered_date::varchar, \'DD-MM-YYYY\') ELSE TO_DATE(TRIM(ordered_date), \'DD/MM/YY\') END) < \'2026-02-01\' union ALL SELECT (Store_id || \'-\' || item_code || \'-\' || Area_name || \'-\' || UPPER(coalesce(lm.city,fi.city)) || \'-\' || variant || \'-\' || UNITS_SOLD || \'-\' || GMV || \'-\' || ordered_date)::text AS order_id, CAST(GMV AS NUMERIC) AS selling_price, date(left(ordered_date,10)) AS order_date, ordered_date, UPPER(coalesce(lm.city,fi.city)) AS CITY, lm.state as State, VARIANT, CAST(BASE_MRP AS NUMERIC) AS MRP, STORE_ID, AREA_NAME, ITEM_CODE, CAST(UNITS_SOLD AS NUMERIC) AS quantity, COALESCE(UPPER(p.CATEGORY), UPPER(fi.L2_category)) AS product_category, p.commonsku, p.tax_Rate as pm_tax_rate, p.cogs, UPPER(fi.PRODUCT_NAME) AS PRODUCT_NAME, COALESCE(UPPER(p.Product_name), REPLACE(UPPER(fi.PRODUCT_NAME), \'anveshan \', \'\')) AS product_name_final, cast(gmv as double PRECISION) AS Selling_Price_final FROM public.anveshan_swiggy_sales_flattened fi LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, swiggy_sku as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY swiggy_sku ORDER BY LENGTH(COALESCE(swiggy_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p ON LOWER(REPLACE(REPLACE(fi.item_code::varchar, \' \', \'\'),\'\"\',\'\')) = LOWER(p.marketplace_sku) LEFT JOIN (select * FROM ( select upper(city::varchar) as City, upper(trim(state::varchar)) as State, upper(trim(\"quick commerce city\"::varchar)) as qc_city_name, row_number() over (partition by upper(trim(\"quick commerce city\"::varchar)) order by 1) as rw FROM public.anveshan_qc_location_mapping ) where rw = 1 ) lm ON lower(lm.qc_city_name) = lower(cast(fi.city as varchar)) where date(left(ordered_date,10)) >= \'2026-02-01\' ;",
